# Search the container for any files that might contain the WAL bytes or database contents
# We'll look for files that contain known item names (e.g., 'banana') or have names like main.db-wal.
import os, fnmatch

matches = []
for root, dirs, files in os.walk("/", topdown=True):
    # skip heavy or special dirs to keep this fast
    dirs[:] = [d for d in dirs if d not in ("proc","sys","dev","run","mnt","media","var","tmp","snap","containerd")]
    for name in files:
        if "main.db" in name or name.endswith("-wal") or name.endswith(".wal") or name.endswith(".db-wal"):
            matches.append(os.path.join(root, name))
# Also search for files containing known strings
candidates = []
needles = [b"banana", b"apple", b"cherry", b"elderberry"]
for root, dirs, files in os.walk("/", topdown=True):
    dirs[:] = [d for d in dirs if d not in ("proc","sys","dev","run","mnt","media","var","tmp","snap","containerd")]
    for name in files:
        path = os.path.join(root, name)
        try:
            st = os.stat(path)
            # only check reasonably small files to keep fast
            if st.st_size > 0 and st.st_size < 200000:
                with open(path, "rb", errors="ignore") as fh:
                    data = fh.read()
                for n in needles:
                    if n in data:
                        candidates.append(path)
                        break
        except Exception:
            continue

print("files whose name suggests WAL/db:", matches)
print("files containing known item names:", candidates)

# Also explicitly check /app and /tmp
print("\n/app listing:")
try:
    print(os.listdir("/app"))
except Exception as e:
    print("err listing /app:", e)

print("\n/tmp listing (small):")
try:
    print(os.listdir("/tmp")[:50])
except Exception as e:
    print("err listing /tmp:", e)
