# Search the filesystem for any file that contains the WAL header "SQLite WAL format 1"
# or that matches the original WAL size (16512). Be more thorough but skip very large dirs.
import os

wal_header = b"SQLite WAL format 1"
found = []
size_matches = []
for root, dirs, files in os.walk("/", topdown=True):
    # prune a few very large or special dirs to keep this reasonably fast
    dirs[:] = [d for d in dirs if d not in ("proc","sys","dev","run",".cache")]
    for name in files:
        path = os.path.join(root, name)
        try:
            st = os.stat(path)
            if st.st_size == 16512:
                size_matches.append(path)
            # only read small files to check header
            if st.st_size > 0 and st.st_size < 200000:
                with open(path, "rb") as fh:
                    data = fh.read(64)
                if wal_header in data:
                    found.append(path)
        except Exception:
            continue

print("Files of size 16512:", size_matches[:20])
print("Files with WAL header:", found[:20])

# Also explicitly check /app, /tmp, and /root for any wal-like files
for d in ("/app","/tmp","/root","/home"):
    try:
        print(f"\nListing {d}:")
        print(os.listdir(d))
    except Exception as e:
        print("err", d, e)

